// LoginPanel.jsx
import React, { useState } from "react";
import axios from "axios";
import { FiEye, FiEyeOff } from "react-icons/fi";
import { useNavigate } from "react-router-dom";
import "./LogInPanel.css";

const LoginPanel = () => {
  const navigate = useNavigate();
  const [isActive, setIsActive] = useState(false);

  // LOGIN
  const [loginNumber, setLoginNumber] = useState("");
  const [loginPassword, setLoginPassword] = useState("");
  const [loginError, setLoginError] = useState("");
  const [showLoginPassword, setShowLoginPassword] = useState(false);
  const [loginLoading, setLoginLoading] = useState(false);

  // REGISTER
  const [registerName, setRegisterName] = useState("");
  const [registerNumber, setRegisterNumber] = useState("");
  const [registerPassword, setRegisterPassword] = useState("");
  const [showRegisterPassword, setShowRegisterPassword] = useState(false);
  const [registerError, setRegisterError] = useState("");
  const [registerLoading, setRegisterLoading] = useState(false);

  // LOGIN SUBMIT
  // LOGIN SUBMIT
  const handleLoginSubmit = async (e) => {
  e.preventDefault();
  setLoginError("");
  setLoginLoading(true);

  try {
    const response = await axios.post("http://localhost:5000/api/login", {  // Ensure this is 5000 (not 8082)
      number: loginNumber,
      password: loginPassword,
    });

const { token, userId } = response.data;
localStorage.setItem("token", token);
localStorage.setItem("userId", userId);

// ✅ Create default accessibility profile if none exists
if (!localStorage.getItem("uaps-profile")) {
  const defaultProfile = {
    settings: {
      textSize: "Medium",
      toggles: {
        readableFont: false,
        simpleMode: false,
        textSize: true,
        zoom: true,
        sound: true,
        captions: true,
        visualAlerts: true,
        quietHours: false
      }
    }
  };

  localStorage.setItem("uaps-profile", JSON.stringify(defaultProfile));
}

navigate("/home");

  } catch (error) {
    setLoginError(error.response?.data?.message || "Invalid number or password");
  } finally {
    setLoginLoading(false);
  }
};


  useEffect(() => {
  const savedNumber = localStorage.getItem("registerNumber");
    if (savedNumber) setLoginNumber(savedNumber);
  }, []);



  // REGISTER SUBMIT
  // REGISTER SUBMIT
  const handleRegisterSubmit = async (e) => {
  e.preventDefault();
  setRegisterError("");
  setRegisterLoading(true);

  try {
    // Register the user
    const regRes = await axios.post("http://localhost:5000/api/register", {
      name: registerName,
      number: registerNumber,
      password: registerPassword,
    });

    const { userId } = regRes.data;
    // Save name and number temporarily for prefill in CreateAccount
    localStorage.setItem("registerName", registerName);
    localStorage.setItem("registerNumber", registerNumber);
    localStorage.setItem("userId", userId);


    if (!localStorage.getItem("uaps-profile")) {
      const defaultProfile = {
        settings: {
          firstName: "",
          lastName: "",
          number: loginNumber || registerNumber || "",
          address: "",
          dateOfBirth: "",
          textSize: "Medium",
          highContrast: false,
          dyslexiaFont: false
        }
      };

      localStorage.setItem("uaps-profile", JSON.stringify(defaultProfile));

    }



    // Redirect to CreateAccount (profile setup)
    navigate("/account");

    } catch (error) {
      setRegisterError(error.response?.data?.error || "Registration failed");
    } finally {
      setRegisterLoading(false);
    }
  };





  return (
    <div className="login-panel-wrapper blue-theme">
      <div className={`container ${isActive ? "active" : ""}`}>
        {/* REGISTER */}
        <div className="form-container sign-up">
          <form onSubmit={handleRegisterSubmit}>
            <div className="logo">
              <img src={`${process.env.PUBLIC_URL}/Uaps bg.png`} alt="UAPS Logo" />
            </div>
            <h1>Create Account</h1>
            <input
              type="text"
              placeholder="Name"
              value={registerName}
              onChange={(e) => setRegisterName(e.target.value)}
              required
            />
            <input
              type="tel"
              placeholder="Phone Number"
              value={registerNumber}
              onChange={(e) => setRegisterNumber(e.target.value)}
              required
            />
            <div className="password-wrapper">
              <input
                type={showRegisterPassword ? "text" : "password"}
                placeholder="Password"
                value={registerPassword}
                onChange={(e) => setRegisterPassword(e.target.value)}
                required
              />
              <span
                className="password-toggle"
                onClick={() => setShowRegisterPassword(!showRegisterPassword)}
              >
                {showRegisterPassword }
              </span>
            </div>
            {registerError && <p className="error">{registerError}</p>}
            <button
            className="hidden"
              // onClick={() => navigate("/account")} // redirect directly
            type="submit" disabled={registerLoading}>
              {registerLoading ? "Registering..." : "Register"}
            </button>
          </form>
        </div>

        {/* LOGIN */}
        <div className="form-container sign-in">
          <form onSubmit={handleLoginSubmit}>
            <div className="logo">
              <img src={`${process.env.PUBLIC_URL}/Uaps bg.png`} alt="UAPS Logo" />
            </div>
            <h1>Log In</h1>
            <input
              type="tel"
              placeholder="Phone Number"
              value={loginNumber}
              onChange={(e) => setLoginNumber(e.target.value)}
              required
            />
            <div className="password-wrapper">
              <input
                type={showLoginPassword ? "text" : "password"}
                placeholder="Password"
                value={loginPassword}
                onChange={(e) => setLoginPassword(e.target.value)}
                required
              />
              <span
                className="password-toggle"
                onClick={() => setShowLoginPassword(!showLoginPassword)}
              >
                {showLoginPassword ? <FiEyeOff /> : <FiEye />}
              </span>
            </div>
            {loginError && <p className="error">{loginError}</p>}
            <button 
            className="hidden"
              // onClick={() => navigate("/home")} // redirect directly
            type="submit" disabled={loginLoading}>
              {loginLoading ? "Logging In..." : "Log In"}
            </button>
          </form>
        </div>

        {/* TOGGLE PANEL */}
        <div className="toggle-container">
          <div className="toggle">
            <div className="toggle-panel toggle-left">
              <h1>Welcome Back!</h1>
              <p>Already have an account?</p>
              <button className="hidden" onClick={() => setIsActive(false)}>
                Log In
              </button>
            </div>
            <div className="toggle-panel toggle-right">
              <h1>Hello, Welcome!</h1>
              <p>Don't have an account?</p>
              <button className="hidden" onClick={() => setIsActive(true)}>
                Register
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPanel;
